6,1232,1367,1459],"pts":""},{"at":"TUN","tos":["TUR","ULS","VAL","VAR","VEN","VER","VIS","VLL","VLP","WIL","WLG","XIA","YEO","ZAK","ZAN"],"offs":[0,118,261,287,375,431,493,594,617,722,774,854,978,1131,1173,1293],"pts":""},{"at":"TUR","tos":["ULS","VAL","VAR","VEN","VER","VIS","VLL","VLP","WIL","WLG","XIA","YEO","ZAK","ZAN"],"offs":[0,188,312,411,560,677,706,825,953,1056,1159,1328,1526,1661,1826],"pts":""},{"at":"ULS","tos":["VAL","VAR","VEN","VER","VIS","VLL","VLP","WIL","WLG","XIA","YEO","ZAK","ZAN"],"offs":[0,135,265,429,541,701,836,865,955,1007,1033,1055,1205,1293],"pts":""},{"at":"VAL","tos":["VAR","VEN","VER","VIS","VLL","VLP","WIL","WLG","XIA","YEO","ZAK","ZAN"],"offs":[0,89,140,199,301,325,437,491,578,708,867,904,1030],"pts":""},{"at":"VAR","tos":["VEN","VER","VIS","VLL","VLP","WIL","WLG","XIA","YEO","ZAK","ZAN"],"offs":[0,121,181,260,351,445,477,546,670,823,930,1050],"pts":""},{"at":"VEN","tos":["VER","VIS","VLL","VLP","WIL","WLG","XIA","YEO","ZAK","ZAN"],"offs":[0,91,225,251,395,481,600,762,953,975,1133],"pts":""},{"at":"VER","tos":["VIS","VLL","VLP","WIL","WLG","XIA","YEO","ZAK","ZAN"],"offs":[0,95,132,252,290,385,494,632,688,793],"pts":""},{"at":"VIS","tos":["VLL","VLP","WIL","WLG","XIA","YEO","ZAK","ZAN"],"offs":[0,101,211,296,381,532,712,829,976],"pts":""},{"at":"VLL","tos":["VLP","WIL","WLG","XIA","YEO","ZAK","ZAN"],"offs":[0,113,173,261,393,554,570,698],"pts":""},{"at":"VLP","tos":["WIL","WLG","XIA","YEO","ZAK","ZAN"],"offs":[0,105,122,141,183,302,391],"pts":""},{"at":"WIL","tos":["WLG","XIA","YEO","ZAK","ZAN"],"offs":[0,68,142,245,307,376],"pts":""},{"at":"WLG","tos":["XIA","YEO","ZAK","ZAN"],"offs":[0,76,115,232,292],"pts":""},{"at":"XIA","tos":["YEO","ZAK","ZAN"],"offs":[0,40,164,231],"pts":""},{"at":"YEO","tos":["ZAK","ZAN"],"offs":[0,147,226],"pts":""},{"at":"ZAK","tos":["ZAN"],"offs":[0,147],"pts":"7J8ukLAZ8gfNE/MDt4UG0A/PD/wq9AOuDMtR50ylzRKPTo9OzWPdsQGtc8/wA5Ud48IBpR2tRIHACIHACJdGuzrFsAShvAS/mgwAz4YDmHX1qQHCZ+MnljefpTbyiimDMswhg1L4VakxgJsBogrUwAHKjgGurAiwvRCwvRC4ggcAiJgFj07eqwOpb5J39Sy0b4tM"}]}$seed$::jsonb as doc;
-- ═══ THE SEED (END) ═══

do $m$
declare
  c_hunked constant text[] := array['public.fleet_job_course(uuid,uuid,uuid)', 'public.fleet_job_plan(uuid)', 'public.hq_board_for(uuid)',
                                    'voyage.reach_passage(uuid,uuid,uuid,numeric)', 'world.best_sales(uuid,uuid)', 'world.board_trips(uuid,jsonb,jsonb)'];
  c_new    constant text[] := array['public.sea_courses_on()', 'public.sea_course(uuid,uuid)', 'public.sale_lines(uuid,uuid,jsonb,jsonb)',
                                    'public.sea_reach_matrix_build()', 'public.sea_reach_matrix_keep()'];
  c_ua     constant uuid := '00000000-0482-4000-8000-0000000000a1';
  v_t0        timestamptz := clock_timestamp();
  v_seed      jsonb := (select s.doc from pg_temp.seed_0482 s);
  v_world     jsonb;
  v_h         record;
  x           record;
  v_def       text;
  v_pre       text;
  v_n         int;
  v_fn_before text;
  v_meta      text;
  v_note      text := '';
  v_lived     boolean := false;
  v_day       timestamptz := date_trunc('day', now() at time zone 'utc') at time zone 'utc';   -- 00:00 UTC of today: before 23:30 UTC, never straddling midnight
  v_a         uuid;
  v_fa        uuid;
  v_lis       uuid;
  v_far       text;
  v_farid     uuid;
  v_gcode     text;
  v_o         jsonb;
  v_ctx       jsonb;
  v_hoist     jsonb;
  v_legs      jsonb;
  v_c         jsonb;
  v_r         jsonb;
  v_texts     text;
  v_first     uuid;
  v_d1        float8[];
  v_d2        float8[];
  g           record;
  a           record;
  v_k         int := 0;
  v_fj        jsonb := (select c.value from public.world_config c where c.key = 'fleet_jobs_enabled');
begin
  perform set_config('statement_timeout', '120s', true);
  perform set_config('lock_timeout', '5s', true);

  -- ── 0. GUARD ──
  if exists (select 1 from public.world_config where key = 'sea_courses_enabled') or to_regclass('public.sea_courses') is not null then
    raise exception '0482 refuses: it has been applied once';
  end if;
  if to_regprocedure('public.fleet_job_sails(uuid,uuid,text[])') is null or to_regprocedure('world.hq_board()') is null
     or to_regprocedure('voyage.path_refusal(jsonb,numeric,numeric,numeric,numeric,numeric,numeric,numeric)') is null
     or to_regprocedure('world.trip_hulls(uuid)') is null or to_regprocedure('voyage.fleet_speed_parts(uuid,boolean)') is null then
    raise exception '0482 refuses: 0481, 0480, 0459 or 0047 is not in this world';
  end if;
  -- THE SEED'S WORLD: the courses were plotted on these harbours, roadsteads and raster (scripts/build-sea-courses.mjs; prod's, before-0482)
  select jsonb_build_object('harbours', count(*),
           'roadsteads', md5(string_agg(p.code || ':' || sr.roadstead_lat::text || ':' || sr.roadstead_lon::text, ',' order by p.code collate "C")),
           'raster', (select md5(r.cells) || ':' || r.cols || 'x' || r.rows || ':' || r.cell_deg from public.sea_raster r where r.id = 1))
    into v_world
    from public.ports p join public.sea_reaches sr on sr.port_id = p.id where p.kind = 'HARBOUR';
  if v_seed is null or v_seed->'world' is distinct from v_world or (v_seed->>'scale')::int <> 10000 then
    raise exception '0482 refuses: the courses were plotted on another world (% / this %): re-run scripts/build-sea-courses.mjs', v_seed->'world', v_world;
  end if;

  -- ── 1. THE PRE-IMAGE ──
  select md5(string_agg(p.oid::regprocedure::text || ':' || md5(replace(pg_get_functiondef(p.oid), E'\r', '')) || ':' || coalesce(p.proacl::text, ''), ',' order by p.oid::regprocedure::text))
    into v_fn_before
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname in ('public', 'cmd', 'world', 'voyage') and p.prokind in ('f', 'p')
     and p.oid <> all (array(select u.q::regprocedure::oid from unnest(c_hunked) u(q)));
  select md5(string_agg(p.oid::regprocedure::text || ':' || coalesce(p.proacl::text, '') || ':' || p.provolatile::text || p.prosecdef::text || coalesce(p.proconfig::text, '') || ':' || p.proowner::text, ',' order by p.oid::regprocedure::text))
    into v_meta from pg_proc p where p.oid = any (array(select u.q::regprocedure::oid from unnest(c_hunked) u(q)));

  -- ── 2. THE KNOB ──
  insert into public.world_config (key, value, description) values
    ('sea_courses_enabled', 'false'::jsonb,
     '0482: THE SWITCH (the owner''s). true: a standing fleet job sails the stored course (public.sea_courses, the browser''s own course between every two harbours) where no merchant lane, coast course or voyage of hers joins them, and each HQ trade card''s act carries its lines whole (each SAIL with its course), so the press needs no chart. false: jobs and cards are 0481''s and 0480''s exactly.');

  -- ── 3. THE TABLES ──
  -- retention: none, bounded by one row a harbour (public.sea_courses: seeded here by scripts/build-sea-courses.mjs, rewritten only by a migration that re-ships it)
  create table public.sea_courses (
    port_id uuid primary key references public.ports(id) on delete cascade,
    tos     text[] not null,
    offs    integer[] not null check (cardinality(offs) = cardinality(tos) + 1),
    pts     bytea not null
  );
  alter table public.sea_courses enable row level security;
  revoke all on table public.sea_courses from public, anon, authenticated;
  comment on table public.sea_courses is
    '0482: the stored course between every two harbours, as the browser plots it (scripts/build-sea-courses.mjs). A row a harbour: the courses to the harbours after it by code ("C" order), tos; each course zigzag base-128 varints of its first point and each point''s difference (lat, lon x 10,000), concatenated in pts, course i at bytes offs[i] .. offs[i+1]. Read by public.sea_course alone. Server only.';
  insert into public.sea_courses (port_id, tos, offs, pts)
  select p.id, array(select jsonb_array_elements_text(r->'tos')), array(select (jsonb_array_elements_text(r->'offs'))::int), decode(r->>'pts', 'base64')
    from jsonb_array_elements(v_seed->'rows') r
    join public.ports p on p.code = r->>'at' and p.kind = 'HARBOUR';

  -- retention: none, bounded by one row (public.sea_reach_matrix: id = 1, rewritten by its trigger when the harbours or their miles change)
  create table public.sea_reach_matrix (
    id     smallint primary key check (id = 1),
    ids    uuid[] not null,
    codes  text[] not null,
    nm     float8[] not null,
    at     timestamptz not null
  );
  alter table public.sea_reach_matrix enable row level security;
  revoke all on table public.sea_reach_matrix from public, anon, authenticated;
  comment on table public.sea_reach_matrix is
    '0482: the sailed miles between every two harbours as voyage.reach_passage builds them (row-major, the harbours by code: ids, codes), kept by public.sea_reach_matrix_keep on every write to public.sea_reaches and on a harbour added, removed, renamed or re-kinded. Read by voyage.reach_passage when its harbours are the call''s own. Server only.';

  -- ── 4. THE RULES ──
  execute $f$
create function public.sea_courses_on()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $body$
  -- 0482: THE SWITCH, read once: world_config sea_courses_enabled.
  select public.wc('sea_courses_enabled') = 'true'::jsonb
$body$
  $f$;

  execute $f$
create function public.sea_course(p_from uuid, p_to uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $body$
-- 0482: THE STORED COURSE from one harbour to another ([[lat, lon], ...], roadstead to roadstead), as the browser's course author plots it
-- (public.sea_courses, scripts/build-sea-courses.mjs); asked the other way, the same water reversed (the door takes every stored course
-- both ways, checked when it was built). Null for the same harbour, a place that is not a harbour, or a pair with none. Not the switch's:
-- its readers ask public.sea_courses_on. cmd.do_sail judges it again, as any course, when the SAIL runs.
declare
  v_a    text := (select p.code from public.ports p where p.id = p_from and p.kind = 'HARBOUR');
  v_b    text := (select p.code from public.ports p where p.id = p_to and p.kind = 'HARBOUR');
  v_rev  boolean;
  r      public.sea_courses%rowtype;
  v_i    int;
  v_s    bytea;
  v_byte int;
  v_z    bigint := 0;
  v_mul  bigint := 1;
  v_vals bigint[] := '{}';
  v_lat  bigint := 0;
  v_lon  bigint := 0;
  v_pts  jsonb[] := '{}';
begin
  if v_a is null or v_b is null or v_a = v_b then
    return null;
  end if;
  v_rev := v_b collate "C" < v_a collate "C";
  select * into r from public.sea_courses c where c.port_id = case when v_rev then p_to else p_from end;
  v_i := array_position(r.tos, case when v_rev then v_a else v_b end);
  if v_i is null then
    return null;
  end if;
  v_s := substring(r.pts from r.offs[v_i] + 1 for r.offs[v_i + 1] - r.offs[v_i]);
  for k in 0 .. length(v_s) - 1 loop
    v_byte := get_byte(v_s, k);
    v_z := v_z + (v_byte & 127) * v_mul;
    if v_byte < 128 then
      v_vals := v_vals || case when v_z % 2 = 0 then v_z / 2 else -(v_z + 1) / 2 end;
      v_z := 0;
      v_mul := 1;
    else
      v_mul := v_mul * 128;
    end if;
  end loop;
  for k in 1 .. coalesce(array_length(v_vals, 1), 0) / 2 loop
    v_lat := v_lat + v_vals[2 * k - 1];
    v_lon := v_lon + v_vals[2 * k];
    v_pts := v_pts || jsonb_build_array(trim_scale(round(v_lat::numeric / 10000, 4)), trim_scale(round(v_lon::numeric / 10000, 4)));
  end loop;
  if coalesce(cardinality(v_pts), 0) < 2 then
    return null;
  end if;
  return (select jsonb_agg(u.x order by case when v_rev then -u.i else u.i end) from unnest(v_pts) with ordinality u(x, i));
end
$body$
  $f$;

  execute $f$
create function public.sale_lines(p_fleet uuid, p_from uuid, p_sale jsonb, p_stops jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $body$
-- 0482: THE LINES OF A SALE (a world.best_sales good: {good, basis, port, units}) from p_from through p_stops (codes): BUY <good> <units>
-- (none when it is her cargo), SAIL to each stop and on to the sale's harbour (public.fleet_job_sails: each with the course a job sails),
-- SELL <good> ALL. {lines: [{text, path}]}, or {missing: <code>} for the first harbour no course reaches. 0481's `best` job wrote these
-- (moved here whole); lit, an HQ trade card's act serves them (0482).
declare
  v_s jsonb;
begin
  v_s := public.fleet_job_sails(p_fleet, p_from, array(select jsonb_array_elements_text(coalesce(p_stops, '[]'::jsonb))) || (p_sale->>'port'));
  if v_s ? 'missing' then
    return v_s;
  end if;
  return jsonb_build_object('lines',
    case when p_sale->>'basis' = 'on_board' then '[]'::jsonb
         else jsonb_build_array(jsonb_build_object('text', format('BUY %s %s', p_sale->>'good', trim_scale(round((p_sale->>'units')::numeric, 2))))) end
    || (v_s->'lines') || jsonb_build_array(jsonb_build_object('text', format('SELL %s ALL', p_sale->>'good'))));
end
$body$
  $f$;

  execute $f$
create function public.sea_reach_matrix_build()
returns table (ids uuid[], codes text[], nm float8[])
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $body$
-- 0482: THE HARBOURS' SAILED MILES, row-major (nm[(i - 1) x n + j] = i -> j), the harbours by code: voyage.reach_passage's own SELECT
-- (0205), word for word, over the harbours alone. public.sea_reach_matrix_keep stores it; the self-assert and proof 185 compare.
declare
  v_ids   uuid[];
  v_codes text[];
  d       float8[];
begin
  select array_agg(p.id order by p.code), array_agg(p.code order by p.code)
    into v_ids, v_codes
    from public.ports p
   where p.kind = 'HARBOUR';
  select array_agg(c.nm order by a.i, c.j) into d
    from unnest(v_ids) with ordinality a(id, i)
    join public.sea_reaches sr on sr.port_id = a.id
   cross join lateral (select sr.reaches || '{}'::jsonb as doc offset 0) m
   cross join lateral (select b.j, (m.doc->>b.c)::float8 as nm from unnest(v_codes) with ordinality b(c, j)) c;
  return query select v_ids, v_codes, d;
end
$body$
  $f$;

  execute $f$
create function public.sea_reach_matrix_keep()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $body$
-- 0482: KEEPS public.sea_reach_matrix TRUE: after any write to public.sea_reaches, and after a harbour is added, removed, renamed or
-- re-kinded, the matrix is built again (public.sea_reach_matrix_build); a world where a harbour has no miles row keeps none (the reader
-- then builds its own, and refuses as before).
begin
  delete from public.sea_reach_matrix;
  insert into public.sea_reach_matrix (id, ids, codes, nm, at)
  select 1, b.ids, b.codes, b.nm, now()
    from public.sea_reach_matrix_build() b
   where b.nm is not null and cardinality(b.nm) = cardinality(b.ids) * cardinality(b.ids);
  return null;
end
$body$
  $f$;

  foreach v_def in array c_new loop
    execute format('revoke all on function %s from public, anon, authenticated, service_role', v_def::regprocedure);
  end loop;
  create trigger sea_reach_matrix_on_reaches after insert or update or delete or truncate on public.sea_reaches
    for each statement execute function public.sea_reach_matrix_keep();
  create trigger sea_reach_matrix_on_ports after insert or delete or truncate or update of code, kind on public.ports
    for each statement execute function public.sea_reach_matrix_keep();
  -- the matrix, built once here (the trigger keeps it from now on)
  insert into public.sea_reach_matrix (id, ids, codes, nm, at)
  select 1, b.ids, b.codes, b.nm, now() from public.sea_reach_matrix_build() b
   where b.nm is not null and cardinality(b.nm) = cardinality(b.ids) * cardinality(b.ids);

  -- ── 5. THE HUNKS (each occurs exactly once in the live body, and reverses) ──
  create temp table hunks_0482 (fn text, ord int, old text, new text) on commit drop;
  insert into hunks_0482 values
  ('public.fleet_job_course(uuid,uuid,uuid)', 1,
$h$      order by (v.origin_port_id = p_from) desc, v.eta desc
      limit 1))$h$,
$h$      order by (v.origin_port_id = p_from) desc, v.eta desc
      limit 1),
    -- 0482 (sea_courses_enabled): else the stored course between the two (public.sea_course: the browser's own, roadstead to roadstead)
    case when public.sea_courses_on() then public.sea_course(p_from, p_to) end)$h$),
  ('public.fleet_job_plan(uuid)', 1,
$h$      v_s := public.fleet_job_sails(f.id, f.port_id, array(select jsonb_array_elements_text(coalesce(v_stops->(s.e->>'port'), '[]'::jsonb))) || (s.e->>'port'));
      continue when v_s ? 'missing';
      v_lines := case when s.e->>'basis' = 'on_board' then '[]'::jsonb
                      else jsonb_build_array(jsonb_build_object('text', format('BUY %s %s', s.e->>'good', trim_scale(round((s.e->>'units')::numeric, 2))))) end
                 || (v_s->'lines') || jsonb_build_array(jsonb_build_object('text', format('SELL %s ALL', s.e->>'good')));$h$,
$h$      -- 0482: the sale's lines are public.sale_lines' (moved there whole: an HQ card's act serves the same lines)
      v_s := public.sale_lines(f.id, f.port_id, s.e, v_stops->(s.e->>'port'));
      continue when v_s ? 'missing';
      v_lines := v_s->'lines';$h$),
  ('public.hq_board_for(uuid)', 1,
$h$                 'stops', coalesce(v_stops->(s.e->>'port'), '[]'::jsonb))))));$h$,
$h$                 'stops', coalesce(v_stops->(s.e->>'port'), '[]'::jsonb)))
                 -- 0482 (sea_courses_enabled): and the trip's lines whole, each SAIL with its course (public.sale_lines): the press sends them
                 -- as they are, no chart needed; none when a leg has no course (the client then plots, as 0480)
                 || coalesce((select jsonb_build_object('lines', l.x->'lines')
                                from (select case when public.sea_courses_on() then public.sale_lines(f.id, f.port_id, s.e, v_stops->(s.e->>'port')) end as x) l
                               where l.x ? 'lines'), '{}'::jsonb))));$h$),
  ('voyage.reach_passage(uuid,uuid,uuid,numeric)', 1,
$h$  select array_agg(c.nm order by a.i, c.j) into d
    from unnest(v_ids) with ordinality a(id, i)
    join public.sea_reaches sr on sr.port_id = a.id
   cross join lateral (select sr.reaches || '{}'::jsonb as doc offset 0) m
   cross join lateral (select b.j, (m.doc->>b.c)::float8 as nm from unnest(v_codes) with ordinality b(c, j)) c;$h$,
$h$  -- 0482: THE MATRIX, KEPT: public.sea_reach_matrix holds this very array when its harbours are these (public.sea_reach_matrix_keep, a
  -- trigger on every write to the harbours' miles or their list); else it is built here, as before
  select m.nm into d from public.sea_reach_matrix m where m.id = 1 and m.ids = v_ids and m.codes = v_codes;
  if d is null then
  select array_agg(c.nm order by a.i, c.j) into d
    from unnest(v_ids) with ordinality a(id, i)
    join public.sea_reaches sr on sr.port_id = a.id
   cross join lateral (select sr.reaches || '{}'::jsonb as doc offset 0) m
   cross join lateral (select b.j, (m.doc->>b.c)::float8 as nm from unnest(v_codes) with ordinality b(c, j)) c;
  end if;$h$),
  ('world.best_sales(uuid,uuid)', 1,
$h$  v_o := world.board_origin(p_fleet);$h$,
$h$  v_o := world.board_origin(p_fleet);
  -- 0482: HER HULLS AND HER SPEED'S PARTS, READ ONCE A CALL: world.board_trips takes them from the context (for this fleet) for every
  -- good's walk; it read them again for each good before. One fleet, one snapshot: the same values, so the same answers.
  v_o := v_o || jsonb_build_object('trip_fleet', p_fleet, 'trip_hulls', world.trip_hulls(p_fleet), 'speed_parts', voyage.fleet_speed_parts(p_fleet));$h$),
  ('world.board_trips(uuid,jsonb,jsonb)', 1,
$h$  v_hulls := world.trip_hulls(p_fleet);
  v_h0 := v_hulls;
  v_speed := voyage.fleet_speed_parts(p_fleet);$h$,
$h$  -- 0482: her hulls and her speed's parts as world.best_sales read them once a call (`trip_hulls`, `speed_parts`, for `trip_fleet`), when
  -- they are this fleet's and of their shape; else read here, as before
  v_hulls := case when p_ctx->>'trip_fleet' = p_fleet::text and jsonb_typeof(p_ctx->'trip_hulls') = 'array' then p_ctx->'trip_hulls'
                  else world.trip_hulls(p_fleet) end;
  v_h0 := v_hulls;
  v_speed := case when p_ctx->>'trip_fleet' = p_fleet::text and jsonb_typeof(p_ctx->'speed_parts') = 'object' then p_ctx->'speed_parts'
                  else voyage.fleet_speed_parts(p_fleet) end;$h$);

  for v_h in select h.fn from hunks_0482 h group by h.fn order by h.fn loop
    v_def := replace(pg_get_functiondef(v_h.fn::regprocedure), E'\r', '');
    v_pre := v_def;
    for x in select * from hunks_0482 h where h.fn = v_h.fn order by h.ord loop
      v_n := (length(v_def) - length(replace(v_def, x.old, ''))) / length(x.old);
      if v_n <> 1 then
        raise exception '0482 self-assert FAIL: hunk % of % occurs % time(s), not once: the deployed body is not what this file was written against', x.ord, x.fn, v_n;
      end if;
      v_def := replace(v_def, x.old, x.new);
    end loop;
    execute v_def;
    v_def := replace(pg_get_functiondef(v_h.fn::regprocedure), E'\r', '');
    for x in select * from hunks_0482 h where h.fn = v_h.fn order by h.ord desc loop
      if (length(v_def) - length(replace(v_def, x.new, ''))) / length(x.new) <> 1 then
        raise exception '0482 self-assert FAIL: hunk % of % is not in the new body once', x.ord, x.fn;
      end if;
      v_def := replace(v_def, x.new, x.old);
    end loop;
    if v_def <> v_pre then
      raise exception '0482 self-assert FAIL: % does not reverse to its pre-image', v_h.fn;
    end if;
  end loop;

  -- ── 6. SELF-ASSERT: the catalog, the knob, the tables ──
  if (select md5(string_agg(p.oid::regprocedure::text || ':' || md5(replace(pg_get_functiondef(p.oid), E'\r', '')) || ':' || coalesce(p.proacl::text, ''), ',' order by p.oid::regprocedure::text))
        from pg_proc p join pg_namespace n on n.oid = p.pronamespace
       where n.nspname in ('public', 'cmd', 'world', 'voyage') and p.prokind in ('f', 'p')
         and p.oid <> all (array(select u.q::regprocedure::oid from unnest(c_hunked) u(q)))
         and p.oid <> all (array(select u.q::regprocedure::oid from unnest(c_new) u(q)))) <> v_fn_before then
    raise exception '0482 self-assert FAIL: another function moved';
  end if;
  if (select md5(string_agg(p.oid::regprocedure::text || ':' || coalesce(p.proacl::text, '') || ':' || p.provolatile::text || p.prosecdef::text || coalesce(p.proconfig::text, '') || ':' || p.proowner::text, ',' order by p.oid::regprocedure::text))
        from pg_proc p where p.oid = any (array(select u.q::regprocedure::oid from unnest(c_hunked) u(q)))) <> v_meta then
    raise exception '0482 self-assert FAIL: the grants, volatility, definer, search path or owner of a hunked body moved';
  end if;
  if (select count(*) from pg_proc p
       where p.oid = any (array['public.sea_courses_on()', 'public.sea_course(uuid,uuid)', 'public.sale_lines(uuid,uuid,jsonb,jsonb)',
                                'public.sea_reach_matrix_build()']::regprocedure[]::oid[])
         and p.provolatile = 's') <> 4
     or public.wc('sea_courses_enabled') <> 'false'::jsonb
     or exists (select 1 from unnest(c_new) u(q)
                 where has_function_privilege('authenticated', u.q::regprocedure, 'execute') or has_function_privilege('anon', u.q::regprocedure, 'execute')
                    or has_function_privilege('service_role', u.q::regprocedure, 'execute'))
     or has_table_privilege('authenticated', 'public.sea_courses', 'select,insert,update,delete')
     or has_table_privilege('anon', 'public.sea_courses', 'select,insert,update,delete')
     or has_table_privilege('authenticated', 'public.sea_reach_matrix', 'select,insert,update,delete')
     or has_table_privilege('anon', 'public.sea_reach_matrix', 'select,insert,update,delete')
     or not (select c.relrowsecurity from pg_class c where c.oid = 'public.sea_courses'::regclass)
     or not (select c.relrowsecurity from pg_class c where c.oid = 'public.sea_reach_matrix'::regclass)
     or (select count(*) from pg_trigger t where t.tgname in ('sea_reach_matrix_on_reaches', 'sea_reach_matrix_on_ports') and not t.tgisinternal) <> 2
     or (select count(*) from public.client_write_grants()) <> 0 then
    raise exception '0482 self-assert FAIL: a read is not STABLE, the knob is not false, a new function or table is a client''s, or a trigger is missing';
  end if;

  -- THE SEED, WHOLE: its rows, courses and bytes; its three probe courses decoded to the point, both ways
  if (select count(*) from public.sea_courses) <> jsonb_array_length(v_seed->'rows')
     or (select sum(cardinality(c.tos)) from public.sea_courses c) <> (v_seed->>'courses')::bigint
     or (select sum(length(c.pts)) from public.sea_courses c) <> (v_seed->>'bytes')::bigint
     or exists (select 1 from public.sea_courses c where c.offs[cardinality(c.offs)] <> length(c.pts) or c.offs[1] <> 0) then
    raise exception '0482 self-assert FAIL: the seed did not land whole (% rows, % courses, % bytes)',
      (select count(*) from public.sea_courses), (select sum(cardinality(c.tos)) from public.sea_courses c), (select sum(length(c.pts)) from public.sea_courses c);
  end if;
  for x in select e->>'from' as f, e->>'to' as t, e->'course' as c from jsonb_array_elements(v_seed->'probes') e loop
    v_c := public.sea_course((select p.id from public.ports p where p.code = x.f and p.kind = 'HARBOUR'), (select p.id from public.ports p where p.code = x.t and p.kind = 'HARBOUR'));
    v_r := public.sea_course((select p.id from public.ports p where p.code = x.t and p.kind = 'HARBOUR'), (select p.id from public.ports p where p.code = x.f and p.kind = 'HARBOUR'));
    if v_c is distinct from x.c or v_r is distinct from (select jsonb_agg(u.p order by u.i desc) from jsonb_array_elements(x.c) with ordinality u(p, i)) then
      raise exception '0482 self-assert FAIL: the stored course % to % does not decode to the course plotted (% / %)', x.f, x.t, left(v_c::text, 200), left(x.c::text, 200);
    end if;
  end loop;
  -- THE DOOR TAKES THEM: from Lisbon to every fourth harbour by code, both ways (cmd.do_sail's question and allowances)
  select p.id into v_lis from public.ports p where p.code = 'LIS' and p.kind = 'HARBOUR';
  for x in
    select p.id, p.code, a0.roadstead_lat as olat, a0.roadstead_lon as olon, b0.roadstead_lat as dlat, b0.roadstead_lon as dlon
      from (select p1.id, p1.code, row_number() over (order by p1.code collate "C") as k from public.ports p1 where p1.kind = 'HARBOUR' and p1.id <> v_lis) p
      join public.sea_reaches a0 on a0.port_id = v_lis
      join public.sea_reaches b0 on b0.port_id = p.id
     where p.k % 4 = 1
  loop
    v_c := public.sea_course(v_lis, x.id);
    if v_c is null
       or voyage.path_refusal(v_c, x.olat, x.olon, x.dlat, x.dlon, public.wc_num('course_join_nm'), 25, 25) is not null
       or voyage.path_refusal(public.sea_course(x.id, v_lis), x.dlat, x.dlon, x.olat, x.olon, public.wc_num('course_join_nm'), 25, 25) is not null then
      raise exception '0482 self-assert FAIL: the stored course LIS - % is missing or the door refuses it: %', x.code, left(v_c::text, 200);
    end if;
    v_k := v_k + 1;
  end loop;
  -- THE MATRIX: kept equal to the one built
  select b.nm into v_d1 from public.sea_reach_matrix_build() b;
  if (select m.nm from public.sea_reach_matrix m where m.id = 1) is distinct from v_d1 or v_d1 is null then
    raise exception '0482 self-assert FAIL: the kept matrix is not the matrix built';
  end if;

  -- ── 7. THE PROBE, rolled back by a raised sentinel (world.best_sales is never asked) ──
  begin
    v_a := public.new_house(c_ua, 'Casa das Rotas 0482', 'PRT');
    select f.id into v_fa from public.fleets f where f.player_id = v_a;
    update public.players p set ducats = 2000000 where p.id = v_a;
    perform cmd.assume_identity(c_ua);
    if (select f.port_id from public.fleets f where f.id = v_fa) is distinct from v_lis then
      raise exception '0482 self-assert FAIL: a Portuguese house does not start at Lisbon';
    end if;

    -- (a) REACH_PASSAGE, the same with the kept matrix and without it (at her navigation, at a short cap and with no cap); the trigger keeps it
    v_c := (select jsonb_agg(to_jsonb(r) order by r.code) from voyage.reach_passage(v_a, v_fa, v_lis, null) r);
    v_r := (select jsonb_agg(to_jsonb(r) order by r.code) from voyage.reach_passage(v_a, v_fa, v_lis, 600) r);
    delete from public.sea_reach_matrix;
    if v_c is null or v_c is distinct from (select jsonb_agg(to_jsonb(r) order by r.code) from voyage.reach_passage(v_a, v_fa, v_lis, null) r)
       or v_r is distinct from (select jsonb_agg(to_jsonb(r) order by r.code) from voyage.reach_passage(v_a, v_fa, v_lis, 600) r) then
      raise exception '0482 self-assert FAIL: voyage.reach_passage answers differently with the kept matrix';
    end if;
    update public.sea_reaches set reaches = reaches where port_id = v_lis;
    if (select m.nm from public.sea_reach_matrix m where m.id = 1) is distinct from v_d1 then
      raise exception '0482 self-assert FAIL: a write to the harbours'' miles did not rebuild the kept matrix';
    end if;

    -- (b) THE LISBON READ'S PIECES, the same with the hoisted hulls and speed parts as without: board_legs once, then every good Lisbon
    --     sells through board_sell (its walks are world.board_trips), with the context world.best_sales builds; board_trips with a buy aboard
    v_o := world.board_origin(v_fa);
    v_hoist := jsonb_build_object('trip_fleet', v_fa, 'trip_hulls', world.trip_hulls(v_fa), 'speed_parts', voyage.fleet_speed_parts(v_fa));
    v_legs := null;
    for g in
      select gd.id, gd.code from public.port_goods pg join public.goods gd on gd.id = pg.good_id
       where pg.port_id = v_lis and public.port_offers(v_lis, gd.id) order by gd.code
    loop
      select * into a from world.board_amount(v_fa, g.id, null);
      v_ctx := v_o || jsonb_build_object(
                 'units', a.units, 'basis', a.basis, 'cost_each', a.cost_each,
                 'src', jsonb_build_object('code', case when a.basis <> 'on_board' then 'LIS' end),
                 'src_cut', false, 'src_name', case when a.basis <> 'on_board' then 'Lisbon' end,
                 'fit', a.basis <> 'on_board', 'lean', true, 'src_passages', null);
      if v_legs is null then
        v_legs := world.board_legs(v_fa, v_ctx || jsonb_build_object('only', '[]'::jsonb));
        -- board_legs and board_trips answer a row a harbour in no fixed order (their readers join by id): compared row by row, by id
        if (select jsonb_agg(e order by e->>'id') from jsonb_array_elements(v_legs) e)
             is distinct from (select jsonb_agg(e order by e->>'id') from jsonb_array_elements(world.board_legs(v_fa, v_ctx || v_hoist || jsonb_build_object('only', '[]'::jsonb))) e) then
          raise exception '0482 self-assert FAIL: board_legs answers differently with the hoisted context';
        end if;
        v_c := (select jsonb_agg(e order by e->>'id') from jsonb_array_elements(world.board_trips(v_fa, v_ctx || jsonb_build_object('buy', jsonb_build_object('units', 10, 'bulk', 1)), v_legs)) e);
        if v_c is distinct from (select jsonb_agg(e order by e->>'id') from jsonb_array_elements(world.board_trips(v_fa, v_ctx || v_hoist || jsonb_build_object('buy', jsonb_build_object('units', 10, 'bulk', 1)), v_legs)) e)
           or v_c is distinct from (select jsonb_agg(e order by e->>'id') from jsonb_array_elements(world.board_trips(v_fa, v_ctx
                || jsonb_build_object('trip_fleet', c_ua, 'trip_hulls', '[]'::jsonb, 'speed_parts', '{}'::jsonb, 'buy', jsonb_build_object('units', 10, 'bulk', 1)), v_legs)) e) then
          raise exception '0482 self-assert FAIL: board_trips answers differently with the hoisted context, or took hulls not her own';
        end if;
      end if;
      if world.board_sell(g.id, v_fa, v_ctx || jsonb_build_object('legs', v_legs))
           is distinct from world.board_sell(g.id, v_fa, v_ctx || v_hoist || jsonb_build_object('legs', v_legs)) then
        raise exception '0482 self-assert FAIL: board_sell answers differently for % with the hoisted context', g.code;
      end if;
      v_gcode := coalesce(v_gcode, g.code);
    end loop;
    if v_gcode is null then
      raise exception '0482 self-assert FAIL: Lisbon sells nothing';
    end if;

    -- (c) DARK: a harbour no remembered course reaches (the nearest within her navigation) has no course a job sails; set_fleet_job
    --     (fleet_jobs_enabled lit for the probe) refuses E_NO_COURSE
    update public.world_config set value = 'true'::jsonb where key = 'fleet_jobs_enabled';
    select p.code, p.id into v_far, v_farid
      from public.ports p join public.sea_reaches sr on sr.port_id = v_lis
     where p.kind = 'HARBOUR' and p.id <> v_lis and public.fleet_job_course(v_fa, v_lis, p.id) is null
       and (sr.reaches->>p.code)::numeric <= public.passage_reach_nm(v_a) * 0.8 and public.sea_course(v_lis, p.id) is not null
     order by (sr.reaches->>p.code)::numeric, p.code limit 1;
    select g2.code into v_gcode
      from public.port_goods pg join public.goods g2 on g2.id = pg.good_id
     where pg.port_id = v_lis and public.port_offers(v_lis, g2.id)
     order by pg.stock_target desc, g2.code limit 1;
    if v_far is null
       or cmd.set_fleet_job(v_fa, 'fixed', jsonb_build_object('good', v_gcode, 'buy', 'LIS', 'sell', v_far))->>'error_code' is distinct from 'E_NO_COURSE' then
      raise exception '0482 self-assert FAIL: dark, no harbour lacks a remembered course within her reach (%), or a fixed route there was not refused E_NO_COURSE', v_far;
    end if;

    -- (d) LIT: the stored course is the course a job sails, the fixed route is set, and the tick sends BUY ALL / SAIL (the stored course) /
    --     SELL ALL: cmd.do_sail takes it and she departs for it
    update public.world_config set value = 'true'::jsonb where key = 'sea_courses_enabled';
    if public.fleet_job_course(v_fa, v_lis, v_farid) is distinct from public.sea_course(v_lis, v_farid) or public.sea_course(v_lis, v_farid) is null then
      raise exception '0482 self-assert FAIL: lit, the course a job sails to % is not the stored course', v_far;
    end if;
    v_r := cmd.set_fleet_job(v_fa, 'fixed', jsonb_build_object('good', v_gcode, 'buy', 'LIS', 'sell', v_far));
    if (v_r->>'ok')::boolean is not true then
      raise exception '0482 self-assert FAIL: lit, the fixed route to % was refused: %', v_far, v_r;
    end if;
    update public.fleet_jobs set since = v_day where fleet_id = v_fa;
    call public.tick_fleet_jobs(false);
    v_first := (select j.last_plan from public.fleet_jobs j where j.fleet_id = v_fa);
    select string_agg(o.raw_text, ' / ' order by o.seq) into v_texts from public.orders o where o.fleet_id = v_fa and o.plan_id = v_first;
    if v_texts is distinct from format('BUY %s ALL / SAIL %s / SELL %s ALL', v_gcode, v_far, v_gcode)
       or (select o.args->'path' from public.orders o where o.plan_id = v_first and o.verb = 'SAIL') is distinct from public.sea_course(v_lis, v_farid)
       or (select f.status from public.fleets f where f.id = v_fa) <> 'SAILING'
       or not exists (select 1 from public.voyages v where v.fleet_id = v_fa and v.status = 'SAILING' and v.dest_port_id = v_farid) then
      raise exception '0482 self-assert FAIL: the fixed job did not send BUY / SAIL (the stored course) / SELL and sail for %: % (%)', v_far, v_texts,
        (select jsonb_agg(jsonb_build_object('t', o.raw_text, 's', o.status, 'e', o.error_code, 'm', o.error_message) order by o.seq) from public.orders o where o.fleet_id = v_fa);
    end if;
    v_note := format('fixed LIS-%s %s by the stored course (%s points)', v_far, v_gcode, jsonb_array_length(public.sea_course(v_lis, v_farid)));
    raise exception using errcode = 'ZX482', message = 'PROBE_ROLLBACK_0482';
  exception when sqlstate 'ZX482' then
    v_lived := true;
  end;
  if not v_lived then
    raise exception '0482 self-assert FAIL: the probe did not run to its end';
  end if;
  if exists (select 1 from public.players p where p.company_name like '% 0482' or p.auth_uid = c_ua)
     or public.wc('sea_courses_enabled') is distinct from 'false'::jsonb or public.wc('fleet_jobs_enabled') is distinct from v_fj
     or (select m.nm from public.sea_reach_matrix m where m.id = 1) is distinct from v_d1
     or public.current_player_id() is not null then
    raise exception '0482 self-assert FAIL: the probe left something behind';
  end if;

  if clock_timestamp() - v_t0 > interval '60 seconds' then
    raise exception '0482 self-assert FAIL: the file took % (budget 60 s)', clock_timestamp() - v_t0;
  end if;
  raise notice '0482 self-assert ok: SEA COURSES (dark) AND A FASTER LISBON READ. % hunks once and reversing; grants and volatility unmoved; no other function moved; five functions and two tables server only; two triggers; sea_courses_enabled false. The seed: % harbours, % courses, % points, % bytes packed (table % bytes, matrix % bytes); three probe courses decoded both ways; % stored courses from Lisbon taken by the door both ways. Probe (rolled back): reach_passage the same with the kept matrix, the trigger keeping it; board_legs, board_trips and board_sell for every good Lisbon sells the same with the hoisted context; dark E_NO_COURSE; lit %, and she departs. % ms.',
    (select count(*) from hunks_0482), jsonb_array_length(v_seed->'rows'), v_seed->>'courses', v_seed->>'points', v_seed->>'bytes',
    pg_total_relation_size('public.sea_courses'), pg_total_relation_size('public.sea_reach_matrix'), v_k, v_note,
    round(extract(epoch from clock_timestamp() - v_t0) * 1000);
end $m$;
